#!/usr/bin/env python3
"""Regenerate the desktop's embedded agent-guard header from its source."""

from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]
SOURCE = ROOT / "tools" / "forkmesh_agent_guard.py"
TARGET = ROOT / "desktop" / "src" / "AgentGuardScript.h"


def render(source: str) -> str:
    delimiter = "PYGUARD"
    if ")" + delimiter + '"' in source:
        raise ValueError("raw-string delimiter appears in guard source")
    return (
        "#pragma once\n\n"
        "// Generated by tools/sync_agent_guard_header.py. Do not edit by hand.\n"
        "// The canonical source is tools/forkmesh_agent_guard.py.\n\n"
        "#include <QString>\n\n"
        "inline QString forkmeshAgentGuardScript()\n"
        "{\n"
        "    return QString::fromUtf8(R\"" + delimiter + "(" + source
        + ")" + delimiter + "\");\n}\n"
    )


def main() -> int:
    TARGET.write_text(render(SOURCE.read_text(encoding="utf-8")), encoding="utf-8")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
